1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Thrown by the create-owner pipeline when 100 or more owners have already been created today
7	 * (counted by {@code registrationDate} equal to the current date). The day's quota is full, so
8	 * no further owner may be created until tomorrow.
9	 *
10	 * <p>Carries the day and its count so {@link OwnerDailyLimitExceededExceptionHandler} can respond
11	 * 429 explaining why the create was rejected.
12	 */
13	public class OwnerDailyLimitExceededException extends Exception {
14	
15	    private final LocalDate date;
16	
17	    private final long count;
18	
19	    public OwnerDailyLimitExceededException(LocalDate date, long count) {
20	        super("Already created " + count + " owners on " + date + "; the daily limit is 100");
21	        this.date = date;
22	        this.count = count;
23	    }
24	
25	    public LocalDate getDate() {
26	        return date;
27	    }
28	
29	    public long getCount() {
30	        return count;
31	    }
32	}
