3	import java.util.List;
4	import java.util.Map;
5	
6	import net.officefloor.plugin.section.clazz.Parameter;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.http.ResponseEntity;
10	
11	/**
12	 * Responds 429 with a JSON body {@code {"errors": ["dailyLimit"]}} when 100 or more owners
13	 * have already been created today.
14	 */
15	public class OwnerDailyLimitExceededExceptionHandler {
16	
17	    public void handle(@Parameter OwnerDailyLimitExceededException ex,
18	            ObjectResponse<ResponseEntity<Map<String, Object>>> response) {
19	        response.send(ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
20	                .body(Map.of("errors", List.of("dailyLimit"))));
21	    }
22	}
